const items = $input.all();
const out = [];
const num = (v) => { const n = Number(v); return Number.isFinite(n) ? n : null; };
for (const it of items) {
  const b = (it.json && it.json.body) ? it.json.body : it.json;
  const speed = num(b.speed_knots);
  const rpm = num(b.engine_rpm);
  const load = num(b.engine_load_pct);
  const fuel = num(b.fuel_consumption_lph);
  const current = num(b.current_knots);
  const wave = num(b.wave_height_m);
  const required = [speed, rpm, load, fuel];
  let reliable = required.every(v => v !== null);
  const reasons = [];
  if (!reliable) reasons.push('missing required telemetry field(s)');
  if (reliable) {
    if (speed < 0 || speed > 40) { reliable = false; reasons.push('speed out of range'); }
    if (rpm < 0 || rpm > 300) { reliable = false; reasons.push('engine RPM out of range'); }
    if (load < 0 || load > 100) { reliable = false; reasons.push('engine load out of range'); }
    if (fuel < 0 || fuel > 100000) { reliable = false; reasons.push('fuel consumption out of range'); }
  }
  out.push({ json: {
    vessel_id: String(b.vessel_id != null ? b.vessel_id : 'unknown'),
    voyage_id: String(b.voyage_id != null ? b.voyage_id : 'unknown'),
    speed_knots: speed,
    engine_rpm: rpm,
    engine_load_pct: load,
    actual_fuel_lph: fuel,
    current_knots: current,
    wave_height_m: wave,
    weather_summary: String(b.weather_summary != null ? b.weather_summary : ''),
    eta_required: b.eta_required != null ? b.eta_required : null,
    distance_remaining_nm: num(b.distance_remaining_nm),
    max_safe_speed_knots: num(b.max_safe_speed_knots),
    data_reliable: reliable,
    data_reliability_reasons: reasons.join('; '),
    recorded_at: new Date().toISOString()
  }});
}
return out;

const current = $("Normalize Data").first().json;
const history = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length > 0);
return [{ json: { current, history, history_count: history.length } }];

const ctx = $input.first().json;
const current = ctx.current || {};
const history = Array.isArray(ctx.history) ? ctx.history : [];
const reliable = history.filter(r => r && r.data_reliable !== false && Number.isFinite(Number(r.actual_fuel_lph)));
const fuels = reliable.map(r => Number(r.actual_fuel_lph));
const mean = fuels.length ? fuels.reduce((a, b) => a + b, 0) / fuels.length : null;
let std = null;
if (fuels.length > 1) {
  const v = fuels.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / (fuels.length - 1);
  std = Math.sqrt(v);
}
const cs = Number(current.speed_knots);
const sim = reliable.filter(r => Number.isFinite(Number(r.speed_knots)) && Math.abs(Number(r.speed_knots) - cs) <= 1.5);
const simFuels = sim.map(r => Number(r.actual_fuel_lph));
const simMean = simFuels.length ? simFuels.reduce((a, b) => a + b, 0) / simFuels.length : null;
const cur = Number(current.actual_fuel_lph);
let z = null;
if (mean != null && std && std > 0 && Number.isFinite(cur)) z = (cur - mean) / std;
const statistical_anomaly = (z != null && Math.abs(z) > 2);
const baseline = {
  sample_size: fuels.length,
  mean_fuel_lph: mean != null ? Number(mean.toFixed(2)) : null,
  std_fuel_lph: std != null ? Number(std.toFixed(2)) : null,
  similar_speed_mean_fuel_lph: simMean != null ? Number(simMean.toFixed(2)) : null,
  z_score: z != null ? Number(z.toFixed(2)) : null,
  statistical_anomaly
};
return [{ json: { current, history, history_count: history.length, baseline } }];

const norm = $("Normalize Data").first().json;
const opt = ($("Optimization Agent").first().json.output) || {};
let rs = Number(opt.recommended_speed_knots);
let rr = Number(opt.recommended_rpm);
let override = false;
const notes = [];
const maxSpeed = Number(norm.max_safe_speed_knots);
if (Number.isFinite(maxSpeed) && rs > maxSpeed) { rs = maxSpeed; override = true; notes.push('recommended speed clamped to max safe speed (' + maxSpeed + ' kn)'); }
if (Number.isFinite(Number(norm.engine_load_pct)) && Number(norm.engine_load_pct) > 95 && rr > Number(norm.engine_rpm)) { rr = Number(norm.engine_rpm); override = true; notes.push('RPM not increased: engine load already above 95%'); }
if (!(rs > 0)) { rs = Number(norm.speed_knots); notes.push('missing recommended speed; held current speed'); override = true; }
if (!(rr > 0)) { rr = Number(norm.engine_rpm); notes.push('missing recommended RPM; held current RPM'); override = true; }
return [{ json: { final_recommended_speed_knots: rs, final_recommended_rpm: rr, safety_override: override, safety_note: notes.join('; ') } }];

const norm = $("Normalize Data").first().json;
const base = ($("Statistical Baseline").first().json.baseline) || {};
const a1 = ($("Fuel Prediction Agent").first().json.output) || {};
const a2 = ($("Optimization Agent").first().json.output) || {};
const a3 = ($("Advisory & Monitoring Agent").first().json.output) || {};
const g = ($("Safety Guardrail").first().json) || {};
const actual = Number(norm.actual_fuel_lph);
const pred = Number(a1.predicted_fuel_lph);
let absErr = null;
if (Number.isFinite(actual) && actual > 0 && Number.isFinite(pred)) absErr = Number((Math.abs(actual - pred) / actual * 100).toFixed(2));
const statAnom = base.statistical_anomaly === true;
const aiAnom = a3.anomaly === true;
const override = g.safety_override === true;
const unreliable = norm.data_reliable === false;
let severity = 'none';
if (unreliable || override || statAnom || a2.meets_eta === false) severity = 'critical';
else if (aiAnom) severity = 'warning';
const alertNeeded = severity !== 'none';
let alertReason = a3.alert_reason || '';
if (unreliable) alertReason = 'Data unreliable: ' + norm.data_reliability_reasons;
else if (override) alertReason = 'Safety override applied: ' + g.safety_note;
else if (statAnom) alertReason = 'Statistical anomaly: fuel z-score ' + base.z_score + ' vs vessel baseline';
else if (a2.meets_eta === false) alertReason = 'No safe setting meets the required ETA';
return [{ json: {
  vessel_id: norm.vessel_id,
  voyage_id: norm.voyage_id,
  speed_knots: norm.speed_knots,
  engine_rpm: norm.engine_rpm,
  engine_load_pct: norm.engine_load_pct,
  actual_fuel_lph: norm.actual_fuel_lph,
  current_knots: norm.current_knots,
  wave_height_m: norm.wave_height_m,
  weather_summary: norm.weather_summary,
  data_reliable: norm.data_reliable,
  predicted_fuel_lph: (a1.predicted_fuel_lph != null ? a1.predicted_fuel_lph : null),
  prediction_confidence: (a1.prediction_confidence != null ? a1.prediction_confidence : null),
  abs_error_pct: absErr,
  baseline_mean_fuel_lph: (base.mean_fuel_lph != null ? base.mean_fuel_lph : null),
  baseline_z_score: (base.z_score != null ? base.z_score : null),
  statistical_anomaly: statAnom,
  recommended_speed_knots: (g.final_recommended_speed_knots != null ? g.final_recommended_speed_knots : null),
  recommended_rpm: (g.final_recommended_rpm != null ? g.final_recommended_rpm : null),
  safety_override: override,
  safety_note: (g.safety_note != null ? g.safety_note : ''),
  expected_fuel_savings_pct: (a2.expected_fuel_savings_pct != null ? a2.expected_fuel_savings_pct : null),
  expected_co2_savings_kg: (a2.expected_co2_savings_kg != null ? a2.expected_co2_savings_kg : null),
  meets_eta: (a2.meets_eta != null ? a2.meets_eta : null),
  meets_safety: (a2.meets_safety != null ? a2.meets_safety : null),
  recommendation: (a3.recommendation != null ? a3.recommendation : ''),
  explanation: (a3.explanation != null ? a3.explanation : ''),
  anomaly: aiAnom,
  severity,
  alert_needed: alertNeeded,
  alert_reason: alertReason,
  recorded_at: norm.recorded_at
} }];

const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length > 0);
const LF = String.fromCharCode(10);
const n = rows.length;
const num = (v) => { const x = Number(v); return Number.isFinite(x) ? x : null; };
const avg = (arr) => arr.length ? arr.reduce((a, b) => a + b, 0) / arr.length : null;
const totalCo2 = rows.map(r => num(r.expected_co2_savings_kg)).filter(v => v != null).reduce((a, b) => a + b, 0);
const savings = rows.map(r => num(r.expected_fuel_savings_pct)).filter(v => v != null);
const errors = rows.map(r => num(r.abs_error_pct)).filter(v => v != null);
const avgSavings = avg(savings);
const avgErr = avg(errors);
const anomalies = rows.filter(r => r.anomaly === true || r.statistical_anomaly === true).length;
const overrides = rows.filter(r => r.safety_override === true).length;
const critical = rows.filter(r => r.severity === 'critical').length;
const vessels = {};
for (const r of rows) {
  const v = String(r.vessel_id != null ? r.vessel_id : 'unknown');
  if (!vessels[v]) vessels[v] = { count: 0, co2: 0, savings: [], errors: [] };
  vessels[v].count++;
  const c = num(r.expected_co2_savings_kg); if (c != null) vessels[v].co2 += c;
  const s = num(r.expected_fuel_savings_pct); if (s != null) vessels[v].savings.push(s);
  const e = num(r.abs_error_pct); if (e != null) vessels[v].errors.push(e);
}
const perVessel = Object.keys(vessels).map(v => {
  const d = vessels[v];
  return '<tr><td>' + v + '</td><td>' + d.count + '</td><td>' + d.co2.toFixed(0) + '</td><td>' + (avg(d.savings) != null ? avg(d.savings).toFixed(1) : 'n/a') + '</td><td>' + (avg(d.errors) != null ? avg(d.errors).toFixed(1) : 'n/a') + '</td></tr>';
}).join('');
const html = '<h2>Fuel-Minimizing Agent - Daily Fleet Report</h2>' +
  '<p><b>Records analysed:</b> ' + n + '</p>' +
  '<ul>' +
  '<li><b>Total expected CO2 savings:</b> ' + totalCo2.toFixed(0) + ' kg</li>' +
  '<li><b>Average expected fuel savings:</b> ' + (avgSavings != null ? avgSavings.toFixed(1) : 'n/a') + '%</li>' +
  '<li><b>Average prediction error (accuracy):</b> ' + (avgErr != null ? avgErr.toFixed(1) : 'n/a') + '%</li>' +
  '<li><b>Anomalies detected:</b> ' + anomalies + '</li>' +
  '<li><b>Safety overrides applied:</b> ' + overrides + '</li>' +
  '<li><b>Critical events:</b> ' + critical + '</li>' +
  '</ul>' +
  '<table border="1" cellpadding="4" cellspacing="0"><tr><th>Vessel</th><th>Records</th><th>CO2 saved (kg)</th><th>Avg savings %</th><th>Avg err %</th></tr>' + perVessel + '</table>';
return [{ json: {
  report_html: html,
  records_analysed: n,
  total_co2_savings_kg: Number(totalCo2.toFixed(0)),
  avg_fuel_savings_pct: avgSavings != null ? Number(avgSavings.toFixed(1)) : null,
  avg_prediction_error_pct: avgErr != null ? Number(avgErr.toFixed(1)) : null,
  anomalies, overrides, critical
} }];
